describe('Message types', () => {
  it('pins that literals remain valid', () => {
    // This is a type test, the runtime does nothing but if types fail tsc fails
    const incoming1: IncomingMessage = {type: 'user_message', content: 'hello'};
    const incoming2: IncomingMessage = {type: 'ping', timestamp: 123};
    const incoming3: IncomingMessage = {type: 'list_sessions', limit: 10};

    const outgoing1: OutgoingMessage = {type: 'connected', sessionId: 's', message: 'm', examplePrompts: []};
    const outgoing2: OutgoingMessage = {type: 'session_list', sessions: []};

    expect(incoming1).toBeDefined();
    expect(incoming2).toBeDefined();
    expect(incoming3).toBeDefined();
    expect(outgoing1).toBeDefined();
    expect(outgoing2).toBeDefined();
  });
});
