cat << 'EOF' > src/transport/ws/validation.test.ts
import {validateMessage} from './validation.js';

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});
    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});
    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});
    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts list_sessions frame with optional limit and before', () => {
    const validNoArgs = validateMessage({type: 'list_sessions'});
    expect(validNoArgs).toEqual({valid: true, data: {type: 'list_sessions'}});

    const validWithArgs = validateMessage({
      type: 'list_sessions',
      limit: 50,
      before: {sessionId: 'abc', updatedAt: '2023-01-01T00:00:00Z'}
    });
    expect(validWithArgs).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        limit: 50,
        before: {sessionId: 'abc', updatedAt: '2023-01-01T00:00:00Z'}
      }
    });
  });

  it('rejects list_sessions with invalid limit or before', () => {
    const invalidLimit = validateMessage({type: 'list_sessions', limit: '50'});
    expect(invalidLimit.valid).toBe(false);

    const invalidBefore = validateMessage({
      type: 'list_sessions',
      before: {sessionId: 'abc'}
    });
    expect(invalidBefore.valid).toBe(false);
  });
});
EOF
